fn append_i64(out:*mut u8,mut at:usize,mut x:i64)->usize{unsafe{if x<0{*out.add(at)=b'-';at+=1;x=-x}if x==0{*out.add(at)=b'0';return at+1}let mut rev=[0u8;24];let mut n=0;while x>0{rev[n]=(b'0'+(x%10)as u8);n+=1;x/=10}while n>0{n-=1;*out.add(at)=rev[n];at+=1}at}}
unsafe fn raw(out:*mut u8,x:i64)->i64{append_i64(out,0,x) as i64}
unsafe fn scaled(out:*mut u8,x:i64,scale:i64,name:&[u8])->i64{if x%scale!=0{return -1}let mut at=append_i64(out,0,x/scale);for b in b".0 ".iter(){*out.add(at)=*b;at+=1}for b in name{*out.add(at)=*b;at+=1}at as i64}
#[no_mangle]
pub unsafe extern "C" fn prefix_conversions_string(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n!=2{return -1}let a=std::slice::from_raw_parts(v,n);if !(a[0]==0||a[0]==1)||!(-1_000_000_000_000..=1_000_000_000_000).contains(&a[1]){return -1}if out.is_null()||cap<8192{return -2}let x=a[1];if x<=0{return raw(out,x)}if a[0]==0{if x>1_000_000_000{return scaled(out,x,1_000_000_000,b"giga")}if x>1_000_000{return scaled(out,x,1_000_000,b"mega")}if x>1000{return scaled(out,x,1000,b"kilo")}if x>100{return scaled(out,x,100,b"hecto")}if x>10{return scaled(out,x,10,b"deca")}}else{if x>1_073_741_824{return scaled(out,x,1_073_741_824,b"giga")}if x>1_048_576{return scaled(out,x,1_048_576,b"mega")}if x>1024{return scaled(out,x,1024,b"kilo")}}raw(out,x)}
